                ${[0, .5, 1].map(t => `<text x="0" y="${y1 - t * (y1 - y0) + 3}" fill="#4d6b60" font-size="9" font-family="JetBrains Mono, monospace">${fmtMoneyShort(max * t)}</text>`).join('')}
                <path d="${area}" fill="url(#tmFill)"/>
