      <>
        <MenuItem
          className="px-2 py-1 text-[10px] rounded-sm cursor-pointer outline-none
            text-text-primary hover:bg-surface-secondary focus:bg-surface-secondary"
          onSelect={() => useEditorStore.getState().setCropModal(id)}
        >
          Crop…
